import React, { useState } from 'react';
import { 
  Box, Typography, ToggleButtonGroup, ToggleButton, 
  FormControl, InputLabel, Select, MenuItem
} from '@mui/material';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, 
  Tooltip, ResponsiveContainer, AreaChart, Area, 
  BarChart, Bar, ReferenceLine, TooltipProps
} from 'recharts';

const ComplaintTrackingChart = ({ analyzedData }) => {
  const [chartType, setChartType] = useState('line');
  const [smoothing, setSmoothing] = useState('none');

  // Extract data for the chart
  const chartData = analyzedData.chunks.map((chunk, index) => ({
    name: `Chunk ${index + 1}`,
    value: chunk.confidence * 100,
    isComplaint: chunk.isComplaint,
  }));

  // Apply smoothing if selected
  const getSmoothedData = () => {
    if (smoothing === 'none') return chartData;

    const factor = smoothing === 'medium' ? 0.5 : 
                   smoothing === 'high' ? 0.7 : 0.3;

    return chartData.map((point, index, array) => {
      if (index === 0) return point;

      const prevValue = array[index - 1].value;
      const smoothedValue = prevValue * factor + point.value * (1 - factor);

      return {
        ...point,
        value: smoothedValue
      };
    });
  };

  const smoothedData = getSmoothedData();

  // Custom tooltip styles
  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      const isComplaint = data.isComplaint;

      return (
        <Box sx={{ 
          backgroundColor: 'rgba(10, 10, 10, 0.9)', 
          p: 1.5,
          border: isComplaint ? '1px solid var(--yellow-highlight)' : '1px solid var(--cyan-accent)',
          boxShadow: isComplaint 
            ? '0 0 10px rgba(202, 255, 112, 0.4)' 
            : '0 0 10px rgba(10, 189, 198, 0.4)',
          borderRadius: '4px',
          fontFamily: 'monospace',
          maxWidth: '200px'
        }}>
          <Typography 
            variant="subtitle2" 
            sx={{ 
              color: isComplaint ? 'var(--yellow-highlight)' : 'var(--cyan-accent)',
              textShadow: isComplaint ? '0 0 3px var(--yellow-highlight)' : '0 0 3px var(--cyan-accent)',
              fontWeight: 'bold',
              textTransform: 'uppercase',
              letterSpacing: '0.05em',
              mb: 0.5
            }}
          >
            {label}
          </Typography>
          <Box sx={{ 
            display: 'flex', 
            justifyContent: 'space-between',
            alignItems: 'center', 
            mb: 0.5 
          }}>
            <Typography variant="caption" sx={{ color: '#aaa' }}>
              Confidence:
            </Typography>
            <Typography 
              variant="body2" 
              sx={{ 
                color: isComplaint ? 'var(--yellow-highlight)' : 'var(--cyan-accent)',
                fontWeight: 'bold'
              }}
            >
              {payload[0].value.toFixed(1)}%
            </Typography>
          </Box>
          <Typography 
            variant="caption" 
            sx={{ 
              display: 'block',
              borderTop: '1px dashed rgba(255,255,255,0.2)',
              pt: 0.5,
              mt: 0.5,
              color: isComplaint ? 'var(--yellow-highlight)' : 'var(--cyan-accent)',
              opacity: 0.8,
              fontStyle: 'italic'
            }}
          >
            Status: {isComplaint ? 'COMPLAINT_DETECTED' : 'NO_COMPLAINT'}
          </Typography>
        </Box>
      );
    }

    return null;
  };

  // The threshold for complaint detection (50%)
  const threshold = 50;

  // Chart containers based on type
  const renderChart = () => {
    const chartProps = {
      data: smoothedData,
      margin: { top: 20, right: 20, left: 0, bottom: 20 },
    };

    // Common axis configuration
    const axisConfig = {
      stroke: '#555',
      strokeDasharray: '3 3',
      tickLine: false,
      tick: { fill: '#aaa', fontSize: 12, fontFamily: 'monospace' }
    };

    // Common grid configuration
    const gridConfig = {
      strokeDasharray: '3 3',
      stroke: 'rgba(255, 255, 255, 0.1)'
    };

    switch (chartType) {
      case 'line':
        return (
          <LineChart {...chartProps}>
            <CartesianGrid {...gridConfig} />
            <XAxis dataKey="name" {...axisConfig} />
            <YAxis 
              {...axisConfig}
              domain={[0, 100]} 
              tickCount={5}
              width={45}
              label={{ 
                value: 'Confidence (%)', 
                angle: -90, 
                position: 'insideLeft',
                style: { textAnchor: 'middle', fill: '#888', fontFamily: 'monospace', fontSize: 12 }
              }}
            />
            <Tooltip content={<CustomTooltip />} />
            <ReferenceLine 
              y={threshold} 
              stroke="rgba(225, 55, 85, 0.8)" 
              strokeDasharray="3 3"
              label={{ 
                value: 'Threshold', 
                position: 'insideTopRight',
                style: { 
                  fill: 'rgba(225, 55, 85, 0.9)',
                  fontSize: 10,
                  fontFamily: 'monospace',
                  textShadow: '0 0 3px rgba(225, 55, 85, 0.5)'
                }
              }}
            />
            <Line 
              type="monotone" 
              dataKey="value" 
              stroke="rgba(0, 255, 163, 0.8)"
              strokeWidth={2}
              dot={(props) => {
                const isComplaint = props.payload.isComplaint;
                return (
                  <svg>
                    <circle
                      cx={props.cx}
                      cy={props.cy}
                      r={isComplaint ? 6 : 4}
                      fill={isComplaint ? 'var(--yellow-highlight)' : 'var(--cyan-accent)'}
                      stroke={isComplaint ? 'rgba(202, 255, 112, 0.8)' : 'rgba(10, 189, 198, 0.8)'}
                      strokeWidth={2}
                      style={{
                        filter: `drop-shadow(0 0 3px ${isComplaint ? 'var(--yellow-highlight)' : 'var(--cyan-accent)'})`
                      }}
                    />
                  </svg>
                );
              }}
              activeDot={{ 
                r: 8, 
                stroke: 'var(--neon-green)', 
                strokeWidth: 2, 
                fill: 'var(--deep-black)',
                strokeDasharray: '0',
                style: {
                  filter: 'drop-shadow(0 0 5px var(--neon-green))',
                  animation: 'pulse 1.5s infinite'
                }
              }}
            />
          </LineChart>
        );

      case 'area':
        return (
          <AreaChart {...chartProps}>
            <defs>
              <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="rgba(0, 255, 163, 0.8)" stopOpacity={0.7} />
                <stop offset="95%" stopColor="rgba(0, 255, 163, 0.8)" stopOpacity={0.1} />
              </linearGradient>
            </defs>
            <CartesianGrid {...gridConfig} />
            <XAxis dataKey="name" {...axisConfig} />
            <YAxis 
              {...axisConfig}
              domain={[0, 100]} 
              tickCount={5}
              width={45}
              label={{ 
                value: 'Confidence (%)', 
                angle: -90, 
                position: 'insideLeft',
                style: { textAnchor: 'middle', fill: '#888', fontFamily: 'monospace', fontSize: 12 }
              }}
            />
            <Tooltip content={<CustomTooltip />} />
            <ReferenceLine 
              y={threshold} 
              stroke="rgba(225, 55, 85, 0.8)" 
              strokeDasharray="3 3"
              label={{ 
                value: 'Threshold', 
                position: 'insideTopRight',
                style: { 
                  fill: 'rgba(225, 55, 85, 0.9)',
                  fontSize: 10,
                  fontFamily: 'monospace',
                  textShadow: '0 0 3px rgba(225, 55, 85, 0.5)'
                }
              }}
            />
            <Area 
              type="monotone" 
              dataKey="value" 
              stroke="rgba(0, 255, 163, 0.8)" 
              strokeWidth={2}
              fillOpacity={1}
              fill="url(#colorValue)"
              dot={(props) => {
                const isComplaint = props.payload.isComplaint;
                return (
                  <svg>
                    <circle
                      cx={props.cx}
                      cy={props.cy}
                      r={isComplaint ? 6 : 4}
                      fill={isComplaint ? 'var(--yellow-highlight)' : 'var(--cyan-accent)'}
                      stroke={isComplaint ? 'rgba(202, 255, 112, 0.8)' : 'rgba(10, 189, 198, 0.8)'}
                      strokeWidth={2}
                      style={{
                        filter: `drop-shadow(0 0 3px ${isComplaint ? 'var(--yellow-highlight)' : 'var(--cyan-accent)'})`
                      }}
                    />
                  </svg>
                );
              }}
              activeDot={{ 
                r: 8, 
                stroke: 'var(--neon-green)', 
                strokeWidth: 2, 
                fill: 'var(--deep-black)',
                strokeDasharray: '0',
                style: {
                  filter: 'drop-shadow(0 0 5px var(--neon-green))',
                  animation: 'pulse 1.5s infinite'
                }
              }}
            />
          </AreaChart>
        );

      case 'bar':
        return (
          <BarChart {...chartProps}>
            <CartesianGrid {...gridConfig} />
            <XAxis dataKey="name" {...axisConfig} />
            <YAxis 
              {...axisConfig}
              domain={[0, 100]} 
              tickCount={5}
              width={45}
              label={{ 
                value: 'Confidence (%)', 
                angle: -90, 
                position: 'insideLeft',
                style: { textAnchor: 'middle', fill: '#888', fontFamily: 'monospace', fontSize: 12 }
              }}
            />
            <Tooltip content={<CustomTooltip />} />
            <ReferenceLine 
              y={threshold} 
              stroke="rgba(225, 55, 85, 0.8)" 
              strokeDasharray="3 3"
              label={{ 
                value: 'Threshold', 
                position: 'insideTopRight',
                style: { 
                  fill: 'rgba(225, 55, 85, 0.9)',
                  fontSize: 10,
                  fontFamily: 'monospace',
                  textShadow: '0 0 3px rgba(225, 55, 85, 0.5)'
                }
              }}
            />
            <Bar 
              dataKey="value" 
              barSize={30}
              shape={(props) => {
                const isComplaint = props.payload.isComplaint;
                return (
                  <g>
                    <rect
                      x={props.x}
                      y={props.y}
                      width={props.width}
                      height={props.height}
                      fill={isComplaint ? 'rgba(202, 255, 112, 0.2)' : 'rgba(10, 189, 198, 0.2)'}
                      stroke={isComplaint ? 'var(--yellow-highlight)' : 'var(--cyan-accent)'}
                      strokeWidth={1}
                      rx={3}
                      ry={3}
                      style={{
                        filter: `drop-shadow(0 0 2px ${isComplaint ? 'var(--yellow-highlight)' : 'var(--cyan-accent)'})`
                      }}
                    />
                  </g>
                );
              }}
            />
          </BarChart>
        );

      default:
        return null;
    }
  };

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      <Box 
        sx={{ 
          display: 'flex', 
          alignItems: 'center', 
          flexWrap: 'wrap',
          justifyContent: 'space-between',
          mb: 2,
          gap: 2
        }}
      >
        <Typography 
          variant="body2" 
          sx={{ 
            fontFamily: 'monospace', 
            color: 'var(--muted-green)',
            textTransform: 'uppercase',
            letterSpacing: '0.05em',
          }}
        >
          <span style={{ color: 'var(--bright-green)', fontWeight: 'bold' }}>
            {analyzedData.complaintPercentage.toFixed(1)}%
          </span> complaints detected
        </Typography>

        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
          <ToggleButtonGroup
            value={chartType}
            exclusive
            onChange={(e, newType) => newType && setChartType(newType)}
            aria-label="chart type"
            size="small"
            sx={{ 
              '.MuiToggleButton-root': {
                border: '1px solid var(--dark-green)',
                color: 'var(--muted-green)',
                textTransform: 'uppercase',
                fontFamily: 'monospace',
                fontSize: '0.7rem',
                letterSpacing: '0.05em',
                '&.Mui-selected': {
                  backgroundColor: 'rgba(0, 255, 163, 0.1)',
                  color: 'var(--neon-green)',
                  boxShadow: '0 0 5px var(--neon-green)',
                  borderColor: 'var(--neon-green)',
                  '&:hover': {
                    backgroundColor: 'rgba(0, 255, 163, 0.2)',
                  }
                },
                '&:hover': {
                  backgroundColor: 'rgba(0, 255, 163, 0.05)',
                },
              }
            }}
          >
            <ToggleButton value="line">Line</ToggleButton>
            <ToggleButton value="area">Area</ToggleButton>
            <ToggleButton value="bar">Bar</ToggleButton>
          </ToggleButtonGroup>

          <FormControl 
            variant="outlined" 
            size="small"
            sx={{ 
              minWidth: 120,
              '.MuiOutlinedInput-root': {
                color: 'var(--muted-green)',
                borderColor: 'var(--dark-green)',
                fontFamily: 'monospace',
                fontSize: '0.7rem',
                '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                  borderColor: 'var(--neon-green)',
                  boxShadow: '0 0 5px var(--neon-green)',
                },
                '&:hover .MuiOutlinedInput-notchedOutline': {
                  borderColor: 'var(--muted-green)',
                },
                '.MuiOutlinedInput-notchedOutline': {
                  borderColor: 'var(--dark-green)',
                },
              },
              '.MuiInputLabel-root': {
                color: 'var(--muted-green)',
                fontFamily: 'monospace',
                fontSize: '0.7rem',
                '&.Mui-focused': {
                  color: 'var(--neon-green)',
                }
              },
              '.MuiMenuItem-root': {
                fontFamily: 'monospace',
                fontSize: '0.7rem',
              }
            }}
          >
            <InputLabel id="smoothing-label">Smoothing</InputLabel>
            <Select
              labelId="smoothing-label"
              value={smoothing}
              onChange={(e) => setSmoothing(e.target.value)}
              label="Smoothing"
            >
              <MenuItem value="none">None</MenuItem>
              <MenuItem value="low">Low</MenuItem>
              <MenuItem value="medium">Medium</MenuItem>
              <MenuItem value="high">High</MenuItem>
            </Select>
          </FormControl>
        </Box>
      </Box>

      <Box 
        sx={{ 
          flex: 1, 
          border: '1px solid var(--dark-green)', 
          borderRadius: '4px',
          background: 'rgba(0, 0, 0, 0.3)',
          p: 2,
          position: 'relative',
          '&::before': {
            content: '""',
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            height: '1px',
            background: 'linear-gradient(90deg, rgba(0,255,163,0) 0%, rgba(0,255,163,0.5) 50%, rgba(0,255,163,0) 100%)',
            boxShadow: '0 0 5px var(--neon-green)',
          },
          '&::after': {
            content: '""',
            position: 'absolute',
            bottom: 0,
            left: 0,
            right: 0,
            height: '1px',
            background: 'linear-gradient(90deg, rgba(0,255,163,0) 0%, rgba(0,255,163,0.5) 50%, rgba(0,255,163,0) 100%)',
            boxShadow: '0 0 5px var(--neon-green)',
          }
        }}
      >
        {smoothedData.length === 0 ? (
          <Box 
            sx={{ 
              height: '100%', 
              display: 'flex', 
              alignItems: 'center',
              justifyContent: 'center' 
            }}
          >
            <Typography 
              variant="body1" 
              sx={{ 
                color: 'var(--muted-green)',
                fontFamily: 'monospace',
                textAlign: 'center'
              }}
            >
              No data available
            </Typography>
          </Box>
        ) : (
          <ResponsiveContainer width="100%" height="100%">
            {renderChart()}
          </ResponsiveContainer>
        )}

        {/* Overlay texture for cyberpunk feel */}
        <Box 
          sx={{ 
            position: 'absolute', 
            top: 0, 
            left: 0, 
            right: 0, 
            bottom: 0, 
            pointerEvents: 'none',
            background: 'repeating-linear-gradient(rgba(0, 0, 0, 0), rgba(0, 0, 0, 0) 2px, rgba(0, 40, 0, 0.05) 2px, rgba(0, 40, 0, 0.05) 4px)',
            opacity: 0.3,
            zIndex: 1
          }} 
        />

        {/* Corner decorations for sci-fi effect */}
        <Box sx={{ 
          position: 'absolute', 
          top: 0, 
          left: 0, 
          width: 20, 
          height: 20, 
          borderTop: '2px solid var(--neon-green)', 
          borderLeft: '2px solid var(--neon-green)',
          opacity: 0.8,
          boxShadow: '0 0 5px var(--neon-green)',
          pointerEvents: 'none'
        }} />
        <Box sx={{ 
          position: 'absolute', 
          top: 0, 
          right: 0, 
          width: 20, 
          height: 20, 
          borderTop: '2px solid var(--neon-green)', 
          borderRight: '2px solid var(--neon-green)',
          opacity: 0.8,
          boxShadow: '0 0 5px var(--neon-green)',
          pointerEvents: 'none'
        }} />
        <Box sx={{ 
          position: 'absolute', 
          bottom: 0, 
          left: 0, 
          width: 20, 
          height: 20, 
          borderBottom: '2px solid var(--neon-green)', 
          borderLeft: '2px solid var(--neon-green)',
          opacity: 0.8,
          boxShadow: '0 0 5px var(--neon-green)',
          pointerEvents: 'none'
        }} />
        <Box sx={{ 
          position: 'absolute', 
          bottom: 0, 
          right: 0, 
          width: 20, 
          height: 20, 
          borderBottom: '2px solid var(--neon-green)', 
          borderRight: '2px solid var(--neon-green)',
          opacity: 0.8,
          boxShadow: '0 0 5px var(--neon-green)',
          pointerEvents: 'none'
        }} />
      </Box>
    </Box>
  );
};

export default ComplaintTrackingChart;
